#!/bin/bash
# Chroot hook, runs inside the image during build-iso after package
# installation. The rite user itself is created at boot by live-config.
set -euo pipefail

# /rite/outputs belongs to the rite user (UID 1000, created by live-config at
# boot), so a ceremony can write there when no RITE-OUT partition is mounted.
mkdir -p /rite/inputs
install -d -o 1000 -g 1000 /rite/outputs

# Completion for the rite CLI, generated by the binary in the image so it
# matches that version.
rite completions bash > /usr/share/bash-completion/completions/rite

# The session owns tty1. No other VT offers a login prompt.
systemctl enable rite-session.service
systemctl mask getty@tty1.service

# The only privilege the rite user has: power the machine off or reboot it.
cat > /etc/sudoers.d/rite <<'EOF'
rite ALL=(root) NOPASSWD: /usr/bin/systemctl poweroff, /usr/bin/systemctl reboot
EOF
chmod 440 /etc/sudoers.d/rite
